-- 0259 turismo_lgtbi (inventario_turismo_lgtbi_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','lgtbi','Almería Pride (Orgullo LGBTI+ de Almería) y espacios asociativos / de ocio en el centro urbano','Capital provincial con una oferta comercial y de ocio nocturno de carácter mixto y baja densidad identitaria permanente. El punto álgido se concentra estacionalmente en el mes de junio con la celebración del Almería Pride, el cual dinamiza la planta hotelera urbana con flujos principalmente de rango provincial y autonómico. Cuenta con un sólido tejido asociativo que vertebra actividades socioculturales puntuales, pero carece de turoperación internacional especializada o certificaciones masivas de hospitalidad LGTBIQ+.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04006','lgtbi','Playa de los Muertos (tramo final catalogado como nudista/naturista con alta afluencia del colectivo)','Destino costero de marcado carácter estacional veraniego. La Playa de los Muertos, reconocida de forma sistemática en rankings nacionales, actúa como un potente polo de atracción para el turismo LGTBIQ+ que busca entornos naturales vírgenes. El tramo final de la cala presenta una consolidada tradición naturista y de socialización para el colectivo, generando un impacto económico indirecto en los servicios de restauración y alojamiento del casco urbano, a pesar de no contar con chiringuitos o infraestructuras hoteleras identitarias exclusivas.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04016','lgtbi','Playa del Sombrerico y locales de ocio nocturno inclusivos en Mojácar Playa','Núcleo turístico maduro que experimenta una fuerte afluencia de visitantes LGTBIQ+ nacionales e internacionales durante el periodo estival (junio a septiembre). La Playa del Sombrerico destaca como espacio de litoral referencial para el colectivo. El tejido hostelero local y residencial muestra un alto grado de hospitalidad inclusiva ("gay-friendly"), complementado con locales nocturnos y chiringuitos de ambiente mixto-diverso. Su puntuación refleja una estacionalidad muy acusada y la ausencia de macroeventos masivos o complejos certificados bajo el sello IGLTA.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','lgtbi','Playa de Los Genoveses (zonas naturistas) y calas del Parque Natural de Cabo de Gata-Níjar (Cala de Media Luna, Cala Carbón)','Municipio con un posicionamiento de nicho basado en el turismo ecosostenible y de naturaleza. Sus playas y calas vírgenes, reguladas bajo estrictas normativas ambientales, albergan tramos de uso naturista con una afluencia consolidada del colectivo LGTBIQ+ internacional (principalmente mercados del norte de Europa). El modelo de alojamiento predominante se compone de casas rurales y guesthouses boutique con políticas de gestión inclusivas que mitigan la estacionalidad del litoral mediante el turismo residencial y de desconexión.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','lgtbi','Orgullo de Cádiz (Cádiz Pride) y Playa de la Victoria (zonas de socialización mixta)','Capital de provincia con un tejido asociativo dinámico y un Orgullo que atrae flujos de toda la comunidad autónoma. Su planta hotelera y hostelera aplica políticas activas de diversidad. Carece de un barrio LGTBI especializado o de turoperación masiva en origen, por lo que su impacto económico se concentra en periodos festivos y de temporada estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16016','lgtbi','Orgullo LGTBI+ del Campo de Gibraltar (sede rotativa/comarcal)','Actúa de forma puntual como dinamizador de la comarca mediante la celebración de eventos de visibilidad y jornadas culturales LGTBIQ+. Su impacto turístico es de rango estrictamente provincial y de corta estancia, atrayendo visitantes del área del Estrecho sin contar con infraestructuras hoteleras de nicho permanentes.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','lgtbi','Cala del Aceite y Calas de Roche (tramos nudistas/LGTBI)','Destino costero maduro con gran poder de atracción estacional (junio a septiembre) para el turismo LGTBIQ+ nacional. Las Calas de Roche y la Cala del Aceite son referentes consolidados de socialización natural y naturista. El sector de apartamentos turísticos y hostelería local presenta una alta rentabilidad derivada de este segmento, aunque la oferta carece de certificaciones internacionales exclusivas.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','lgtbi','Festivales culturales inclusivos, locales de ocio diverso en el centro histórico y red de alojamientos "friendly"','Gran polo urbano que aprovecha su patrimonio enoturístico y flamenco para atraer al turismo LGTBIQ+ cultural de poder adquisitivo medio-alto. Organiza ciclos de cine, conferencias y eventos de visibilidad que complementan su oferta de ocio nocturno mixto. Presenta un volumen empresarial especializado en crecimiento constante.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','lgtbi','Sotogrande Pride Polo / Torneos inclusivos y resorts de alto standing de la urbanización Sotogrande','Destino de lujo residencial y deportivo con un posicionamiento premium. Hoteles y clubes de polo de Sotogrande organizan y patrocinan eventos deportivos y sociales orientados al colectivo de rentas altas, especialmente del mercado británico y europeo central. Destaca por su seguridad, exclusividad y alta inversión por turista, desmarcándose del turismo masivo.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','lgtbi','Playa de Bolonia (zona de El Lentiscal / duna), Playa de Valdevaqueros y guesthouses inclusivas','Icono del turismo deportivo y de naturaleza con un ambiente marcadamente liberal e internacional. Los tramos naturales de la Playa de Bolonia son puntos calientes de afluencia LGTBIQ+. Cuenta con hoteles boutique, campings y alojamientos que operan bajo estándares informales de inclusión internacional, atrayendo flujos continuos de Europa central durante más de seis meses al año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','lgtbi','Festival de Cultura LGTBIQ+ rural (jornadas de visibilidad)','Ejemplo de dinamización turística y social en el entorno rural. Su festival de carácter anual atrae flujos de la provincia y zonas limítrofes, aportando un impacto puntual en las casas rurales y la restauración del municipio en fechas específicas de la primavera.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','lgtbi','Orgullo de Córdoba, red de hoteles con sello inclusivo y locales de ocio diverso en el casco histórico','Destino patrimonial de primer orden con un posicionamiento LGTBIQ+ enfocado al turismo de fin de semana y congresos. Su Orgullo anual y el festival de cine especializado vertebran la oferta cultural. El tejido hostelero de la judería está altamente preparado para el sector receptivo internacional, rompiendo la estacionalidad de sol y playa mediante el turismo cultural y gastronómico.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','lgtbi','Playa de Cantarriján (playa nudista con chiringuitos e infraestructura identitaria de referencia nacional)','Destino costero clave gracias a la Playa de Cantarriján, situada en el paraje natural de los Acantilados de Maro-Cerro Gordo. Esta playa es considerada uno de los epicentros naturistas y LGTBIQ+ de Andalucía, contando con chiringuitos históricos especializados que organizan eventos y fiestas propias. Atrae turismo nacional e internacional (principalmente francés, alemán y británico) y genera un fuerte impacto económico indirecto en los alojamientos del municipio.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','lgtbi','Orgullo de Granada, locales de ocio especializado en el distrito centro / Realejo, y alojamientos boutique inclusivos','Ciudad universitaria y cultural con un tejido empresarial de ocio nocturno y comercial LGTBIQ+ maduro. El Orgullo y las programaciones de cultura inclusiva mantienen una afluencia constante. Su planta hotelera en barrios históricos como el Albaicín está integrada en plataformas de hospitalidad inclusiva, registrando reservas directas de turistas internacionales de perfil joven y de mediana edad durante todo el año, mitigando los meses estivales gracias al turismo de invierno y universitario.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','lgtbi','Comunidades y alojamientos de ecoturismo residencial LGTBIQ+ en la Alpujarra','Capital de la Alpujarra granadina, caracterizada por un modelo de turismo rural, multicultural y alternativo. Cuenta con una comunidad residencial internacional LGTBIQ+ estable que gestiona y demanda cortijos, retiros de bienestar y alojamientos rurales eco-friendly. Su estacionalidad es baja gracias al clima y al perfil de turista que busca estancias prolongadas y desconexión.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','lgtbi','Playa de Castilla (tramos vírgenes occidentales colindantes con Doñana, de uso naturista y alta concurrencia LGTBIQ+)','Destino costero condicionado por su entorno protegido. El sector de la Playa de Castilla de difícil acceso peatonal funciona estacionalmente como refugio de privacidad para el colectivo. Genera un impacto económico indirecto en la planta de campings y establecimientos hoteleros de Matalascañas, atrayendo principalmente a turistas de Andalucía occidental y Extremadura durante la temporada estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','lgtbi','Orgullo de Huelva / WofestHuelva (Muestra de Cine que integra secciones de diversidad)','Núcleo urbano con actividades de visibilidad concentradas de forma estricta en el mes de junio. Carece de un hub empresarial o de ocio permanente exclusivo del colectivo, pero su oferta hotelera se comercializa bajo sellos generalistas inclusivos para absorber la demanda cultural de fin de semana y captar turismo corporativo regional.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','lgtbi','Playa del Hoyo y alojamientos accesibles / inclusivos de la Costa de la Luz','Localidad pesquera y turística que ha consolidado la Playa del Hoyo como espacio preferente de socialización diversa en su pinar marítimo. Su tejido hotelero tradicional y de apartamentos registra una creciente cuota de mercado LGTBIQ+ nacional e internacional de origen portugués por su proximidad fronteriza, mostrando una alta fidelización estacional.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','lgtbi','Red de alojamientos boutique e iniciativas de turismo cultural con enfoque diverso en ciudad Patrimonio de la Humanidad','Polo turístico patrimonial que destaca por la adaptación de sus palacios y alojamientos de encanto a las demandas del sector LGTBIQ+ premium. Su oferta rompe por completo la estacionalidad de litoral, atrayendo flujos continuos de parejas internacionales con alto gasto en destino enfocado en el oleoturismo y la cultura.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','lgtbi','Orgullo de Jaén y locales de restauración inclusiva en el centro histórico','Capital de provincia con infraestructuras limitadas al ámbito asociativo y de ocio nocturno mixto. El Orgullo provincial dinamiza los servicios hoteleros del casco urbano en fechas específicas del verano. Presenta un fuerte margen de crecimiento en infraestructuras específicas.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','lgtbi','Playa de Benalnatura (una de las playas nudistas/LGTBI pioneras de España, dotada de chiringuito e infraestructuras integradas)','Destino costero referencial de la Costa del Sol. Benalnatura es una cala exclusiva y protegida acantilada que funciona como un potente imán turístico permanente para visitantes de toda Europa. La localidad cuenta con una infraestructura hotelera madura y alta conectividad aeroportuaria, complementando perfectamente la oferta comercial y residencial del municipio colindante de Torremolinos.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','lgtbi','Playa de ArtolaCabopino (zona de las Dunas de Artola) y complejos hoteleros de gran lujo con certificaciones internacionales de hospitalidad','Epicentro del turismo residencial y vacacional de lujo en España. El tramo dunar de la Playa de Cabopino es un hito de socialización LGTBIQ+ internacional muy cotizado. Hoteles de cinco estrellas y resorts del municipio forman parte activa de redes especializadas (como IGLTA), ofreciendo servicios premium con un altísimo impacto económico y un perfil de cliente internacional (británico, árabe y estadounidense) de rentas altas que exige máxima discreción y exclusividad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','lgtbi','Orgullo de Málaga, locales especializados en el Soho y Centro Histórico, y red hotelera internacional inclusiva','Gran hub urbano, cultural y tecnológico en pleno auge. La capital ha sabido posicionar sus barrios céntricos (Soho, entorno de la Alameda) como espacios abiertos y diversos con una alta densidad de negocios especializados. Su Orgullo anual tiene un impacto económico millonario. Su excelente conectividad (AVE, Aeropuerto) y su potente oferta museística garantizan un turismo LGTBIQ+ internacional recurrente y desestacionalizado durante todo el año, consolidándola como uno de los grandes referentes a nivel nacional.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29901','lgtbi','Barrio de La Nogalera (epicentro comercial y de ocio), Torremolinos Pride (macroevento internacional), Playa de El Bajondillo (Edén Beach) y la mayor concentración hotelera y residencial especializada','Icono e hito del turismo LGTBIQ+ a nivel mundial. El municipio opera como una auténtica "ciudad santuario" y hub identitario con más de un centenar de locales comerciales, discotecas y bares especializados concentrados en La Nogalera. Dispone de complejos hoteleros masivos y certificados orientados exclusivamente al colectivo. Su Pride atrae a más de 60.000 turistas de Europa y América cada año, generando un impacto económico masivo. Funciona de manera desestacionalizada gracias a congresos, eventos invernales y una potente comunidad residencial internacional permanente. Es el pilar indiscutible del turismo LGTBIQ+ del sur de Europa.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','lgtbi','Huesca la Diversa (Muestra de Cine LGTBIQ+ y jornadas de visibilidad) y red de alojamientos urbanos inclusivos','Capital provincial con una oferta centrada en eventos culturales puntuales durante el año. Su festival de cine y actividades asociativas atraen flujos de corta estancia de carácter principalmente autonómico y provincial. Carece de un hub comercial o de ocio nocturno identitario permanente, pero la planta hotelera local está adaptada para el turismo de congresos y escapadas culturales mixtas.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','lgtbi','Actos del Orgullo LGTBIQ+ de Teruel y alojamientos con distintivo de hospitalidad turística','Municipio con actividad concentrada de manera estricta en la semana del Orgullo. La infraestructura hostelera del centro histórico absorbe una demanda de proximidad (Aragón y Comunidad Valenciana). Funciona como un recurso de dinamización turística muy acotado en el tiempo, sin tejido empresarial especializado permanente.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','lgtbi','Zinentiendo (Muestra Internacional de Cine LGTBIQ+), Orgullo de Zaragoza, y ejes de ocio/comercio en el Casco Viejo y distrito Centro','Gran nodo urbano y de transportes que actúa como el principal polo de atracción del colectivo en el valle del Ebro. Su muestra de cine es un referente de prestigio regional con gran afluencia. Dispone de un tejido consolidado de locales de ocio nocturno, librerías y comercios especializados en el centro histórico. Su excelente conectividad por alta velocidad (AVE) facilita un flujo constante de turismo de fin de semana, cultural y de negocios procedente de Madrid, Cataluña y el País Vasco, rompiendo la estacionalidad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','lgtbi','Orgullo de Avilés y programación cultural de diversidad en el Centro Niemeyer','Tercer polo urbano asturiano que ha reforzado su posicionamiento mediante eventos de visibilidad y una agenda cultural vanguardista e inclusiva vinculada al Centro Niemeyer. Su Orgullo congrega a miles de personas de todo el noroeste peninsular. Genera un impacto directo en la hostelería local durante la época estival y los fines de semana de programación especializada.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','lgtbi','Playa de Serín (referente de litoral nudista/LGTBI), locales de ocio especializado en Cimavilla y festival de cultura inclusiva','Destino costero y urbano de prestigio en el Cantábrico. La Playa de Serín es un espacio natural aislado muy consolidado para el colectivo. El barrio histórico de Cimavilla alberga una densidad madura de establecimientos hosteleros y de ocio identitarios o declaradamente inclusivos. Atrae un turismo norteño y estatal de perfil cultural y vacacional de verano, caracterizado por una alta fidelidad y un gasto medio-alto en restauración y comercio local.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','lgtbi','Orgullo de Asturias (sede principal/manifestación autonómica) y red de alojamientos boutique inclusivos','Capital institucional del Principado que centraliza las grandes movilizaciones del Orgullo autonómico, lo que genera picos de ocupación hotelera total en el mes de junio. Su oferta habitual se enfoca al turismo cultural, monumental y gastronómico desestacionalizado. La planta hotelera urbana cuenta con altos estándares de hospitalidad inclusiva para captar el turismo de escapadas de parejas del resto de España.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90023','lgtbi','Playa de Es Cavallet (playa LGTBI/nudista de fama internacional con el emblemático chiringuito Chiringay) y resorts de lujo inclusivos','Municipio costero de impacto global. Es Cavallet es considerada una de las playas LGTBIQ+ más icónicas del mundo, cuyo chiringuito identitario opera como polo de socialización diurna para celebridades, prescriptores y turistas de rentas muy altas. Alberga una planta hotelera boutique y villas de lujo integradas en la International LGBTQ+ Travel Association (IGLTA). Su impacto económico es masivo, traccionando el sector del alquiler de vehículos, la restauración premium y los servicios exclusivos náuticos durante todo el verano.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','lgtbi','Calas de uso naturista consolidado (como El Mago) y complejos hoteleros internacionales con certificaciones de diversidad','Destino costero maduro con un posicionamiento mixto muy potente. La playa de El Mago es un referente histórico para el turismo LGTBIQ+ y naturista europeo. El municipio cuenta con grandes cadenas hoteleras internacionales que forman a su personal bajo estrictos protocolos de hospitalidad inclusiva. Registra una afluencia masiva de mercados emisores tradicionales como el británico y el alemán, con un impacto directo en la oferta de ocio náutico y restauración de la zona.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','lgtbi','Palma Pride / Ella International Lesbian Festival (macroevento especializado de referencia mundial), locales de ocio en el barrio de Gomila y el centro histórico, y hoteles Adults Only de alta gama','Gran capital insular y hub logístico. Destaca internacionalmente por albergar el Ella Festival, uno de los eventos de turismo lésbico y queer femenino más importantes del planeta, atrayendo a miles de mujeres de más de 30 países. El dinamismo empresarial en barrios como Gomila y Santa Catalina ofrece una amplia infraestructura de ocio permanente. Su conectividad aeroportuaria directa con toda Europa Occidental permite mantener flujos turísticos desestacionalizados de fin de semana durante el otoño y la primavera, enfocados en el turismo cultural, gastronómico y náutico premium.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','lgtbi','Macarelleta y Cala Pilar (tramos naturistas de alta concurrencia LGTBIQ+), y guesthouses eco-friendly inclusivas','Posicionamiento premium enfocado al turismo de desconexión, naturaleza y sostenibilidad. Las calas vírgenes del norte y sur atraen a un perfil LGTBIQ+ de poder adquisitivo medio-alto que huye de las aglomeraciones. Aunque carece de grandes hubs urbanos de ocio nocturno exclusivo, el municipio destaca por su hospitalidad "friendly" generalizada en hoteles de interior y agroturismos, registrando una altísima tasa de fidelidad estacional (junio a septiembre).','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','lgtbi','Las Palmas de Gran Canaria Pride, Gala Drag Queen del Carnaval (evento de trascendencia mundial), locales de ocio en el barrio de Triana y Vegueta, y Playa de Las Canteras (zona de la Cícer / Peña de ','Gran capital atlántica con una de las ofertas socioculturales más diversas de Europa. La Gala Drag Queen es un hito de la radiodifusión y el turismo masivo que atrae flujos globales cada febrero, generando un impacto económico multimillonario con ocupación hotelera del 100%. Su tejido comercial y de ocio permanente está completamente consolidado. Gracias a su clima subtropical y conectividad aérea total con el continente europeo, funciona de manera totalmente desestacionalizada durante los 12 meses del año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35015','lgtbi','Playas de Sotavento y Playa de Cofete (tramos naturistas internacionales), e infraestructuras hoteleras inclusivas en Morro Jable','Municipio costero especializado en el turismo de viento, deportes náuticos y grandes extensiones de playas salvajes. Sus tramos nudistas son un punto caliente de fuerte tradición para el colectivo del norte de Europa (principalmente mercados alemán, británico y holandés). La planta alojativa cuenta con importantes resorts de cadenas internacionales adaptados al sello inclusivo. Registra una alta fidelización invernal, rompiendo la estacionalidad europea gracias al clima canario.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','lgtbi','Centro Comercial Yumbo Centrum (único centro comercial del mundo 100% especializado y enfocado al público LGTBIQ+), Maspalomas Pride / Winter Pride (macroeventos internacionales), Kiosco número 7 en l','Máxima puntuación de la escala. Es el epicentro definitivo del turismo LGTBIQ+ a nivel global. El Yumbo Centrum alberga más de 200 negocios especializados (bares, discotecas, saunas, restaurantes) que operan los 365 días del año. Sus Prides de mayo y noviembre atraen a más de 100.000 turistas internacionales por edición, inyectando cientos de millones de euros directos en la economía insular. El entorno natural de las Dunas de Maspalomas y su Kiosco 7 son iconos globales de socialización. Su planta hotelera exclusiva (con opciones "clothing-optional" y resorts solo para adultos) no tiene rival en Europa, registrando ocupaciones medias superiores al 85% durante todo el año, lo que elimina por completo cualquier tipo de estacionalidad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','lgtbi','Playa de Diego Hernández (playa salvaje de uso naturista/LGTBI referencial) y establecimientos hoteleros de gran lujo con certificaciones internacionales de hospitalidad (IGLTA)','Uno de los municipios con mayor facturación turística y de rentas más altas de España (Costa Adeje). La Playa de Diego Hernández es un hito natural de socialización diversa muy reconocido. El destino destaca por captar un perfil de turista LGTBIQ+ premium e internacional que busca resorts de cinco estrellas, spas de lujo, alta gastronomía y campos de golf. Sus infraestructuras hoteleras aplican los mayores estándares de inclusión corporativa mundiales, logrando un gasto en destino excepcionalmente alto y una ocupación constante todo el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90776','lgtbi','Arnold Classic Europe (eventos deportivos con alta participación e inclusión del colectivo), zonas de ocio nocturno en Playa de las Américas y Playa de las Vistas','Zona turística madura y densamente poblada que comparte con Adeje el gran eje vacacional del sur de Tenerife. Playa de las Américas cuenta con una sólida y variada oferta de locales nocturnos, pubs y discotecas con una atmósfera plenamente abierta e inclusiva que atrae masivamente al turismo británico, italiano y escandinavo. Su clima permanente garantiza un flujo económico constante sin picos de estacionalidad veraniega, apoyado fuertemente por el turismo residencial de larga estancia de mayores de 50 años.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','lgtbi','Festival ARN Culture Pride (macroevento internacional de cultura, pensamiento y visibilidad LGTBIQ+), locales de ambiente en el centro histórico, Playa Bollullo y Playa Jardín','Histórico santuario de libertad y turismo inclusivo en el norte de Tenerife. Destaca de forma sobresaliente en el panorama internacional por el ARN Culture Pride, un festival de referencia que combina activismo, conferencias de filósofos e intelectuales mundiales, música y entrega de premios globales, atrayendo a miles de visitantes con un perfil cultural de alto nivel. El centro urbano cuenta con un hub de ocio tradicionalmente diverso muy bien integrado en la vida local. Su planta hotelera, de corte clásico pero renovada, trabaja de la mano con turoperadores europeos especializados para garantizar flujos constantes durante los meses de invierno.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','lgtbi','Santa Cruz Pride, Playa de Las Gaviotas (playa nudista con fuerte arraigo en el colectivo) y eventos culturales de diversidad','Capital tinerfeña que concentra el tejido institucional y asociativo. Su Orgullo anual y las actividades complementarias durante su famoso Carnaval dinamizan fuertemente los hoteles urbanos. La Playa de Las Gaviotas, de arena negra volcánica y carácter seminatural, ofrece un espacio seguro de socialización naturista. Su posicionamiento turístico para el colectivo se enfoca principalmente en las escapadas culturales, de compras y cruceros, operando de manera desestacionalizada.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','lgtbi','Playa de La Salvé (tramos de dunas de uso naturista y alta concurrencia del colectivo)','Destino costero con una marcada estacionalidad estival (julio y agosto). Sus extensas dunas e infraestructuras de playa atraen flujos turísticos del País Vasco y del interior de Cantabria, impactando positivamente de forma puntual en la ocupación de cámpings, apartamentos turísticos y hostelería local.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','lgtbi','Playa de Somo (zona este / dunas) y Playa de Langre (entorno acantilado de fuerte tradición naturista/LGTBIQ+)','Polo de atracción para el turismo deportivo y de naturaleza en el norte de España. Las playas de Langre y Somo son referentes consolidados de socialización natural. Atrae a un perfil LGTBIQ+ joven e internacional vinculado al surf y al turismo ecológico, lo que genera una alta rentabilidad en escuelas de surf, hostales boutique y guesthouses inclusivas durante el periodo estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','lgtbi','Orgullo de Cantabria (Santander Pride), locales de ocio diverso en el entorno de Puertochico / Río de la Pila, y Playa de Somocuevas (en el cercano municipio de Piélagos, pero polarizada por la capita','Capital autonómica que centraliza el tejido asociativo y el Orgullo regional, atrayendo flujos del norte peninsular y Madrid. Su oferta hostelera de alta gama y su programación cultural en el Centro Botín captan un turismo urbano de poder adquisitivo medio-alto. La estacionalidad del litoral se rompe parcialmente mediante el turismo de congresos y escapadas de fin de semana durante el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','lgtbi','Orgullo de Albacete y red de locales de ocio inclusivo en "La Zona" (casco urbano)','Núcleo urbano manchego con actividades concentradas en el mes de la diversidad. Su infraestructura hotelera absorbe una demanda de proximidad y carácter autonómico. Carece de turoperación internacional especializada o de un hub identitario permanente exclusivo, basando su oferta en la hostelería mixta.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13001','lgtbi','Festival "Plural" (Jornadas de Cultura y Visibilidad LGTBIQ+) y red de alojamientos rurales inclusivos','Importante nodo ferroviario y vitivinícola que utiliza sus eventos culturales estacionales para atraer turismo de interior. El impacto económico se concentra en fechas muy específicas del año, dinamizando la planta hotelera mediana y los recursos de restauración locales a través de conferencias y certámenes artísticos.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','lgtbi','Orgullo de Ciudad Real y red asociativa cultural','Actividad centrada estrictamente en el ámbito institucional y asociativo provincial. Su conectividad mediante alta velocidad (AVE) genera picos de visitas de corta estancia para eventos de fin de semana, aunque el tejido comercial permanente especializado sigue siendo muy limitado.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','lgtbi','Orgullo de Cuenca, alojamientos boutique de encanto inclusivos en el Casco Antiguo e iniciativas de turismo de naturaleza y arte contemporáneo','Ciudad Patrimonio de la Humanidad con un posicionamiento enfocado al turismo de escapadas culturales de fin de semana, fuertemente traccionado por el mercado emisor de Madrid gracias al AVE. Los hoteles de interior aplican directrices "friendly" y de alta hospitalidad, registrando visitas desestacionalizadas de parejas de rentas medias-altas atraídas por su oferta monumental y paisajística.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19130','lgtbi','Orgullo de Guadalajara y eventos culturales diversos integrados en la red teatral local','Destino fuertemente influenciado por su proximidad a la Comunidad de Madrid. Su Orgullo anual atrae flujos de la provincia y del Corredor del Henares. Funciona principalmente como un recurso de proximidad y excursiones de un día, careciendo de una planta alojativa de nicho propia.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','lgtbi','Toledo Entiende (Orgullo de Toledo), alojamientos boutique de gran lujo e iniciativas de turismo cultural y patrimonial inclusivo','Destino de primer orden internacional. Su festival anual "Toledo Entiende" está plenamente consolidado a nivel regional. Los alojamientos en cigarrales y hoteles históricos del casco antiguo cuentan con altos estándares de formación en diversidad, captando un importante volumen de turismo internacional que pernocta en la ciudad. Consigue romper la estacionalidad gracias a su potente oferta cultural, de congresos y gastronómica durante los doce meses del año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','lgtbi','Orgullo de Ávila y red de alojamientos patrimoniales con distintivos de hospitalidad','Destino monumental cuya actividad identitaria se concentra en jornadas estacionales de visibilidad. Su planta hotelera en el interior de la muralla absorbe flujos de proximidad del mercado emisor madrileño. Carece de un hub empresarial o de ocio permanente exclusivo del colectivo, operando principalmente como turismo de escapada mixta de fin de semana.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','lgtbi','Orgullo de Burgos, locales de ocio inclusivo en el centro histórico y actividades del festival de cine de diversidad','Importante nodo urbano y del Camino de Santiago. Cuenta con un tejido asociativo consolidado que dinamiza la agenda cultural. Sus establecimientos hoteleros y hosteleros registran flujos estables de turistas nacionales y peregrinos internacionales del colectivo LGTBIQ+ que demandan turismo cultural y gastronómico, logrando romper la estacionalidad estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','lgtbi','Orgullo de León, locales de ocio nocturno y comercio especializado en el Barrio Húmedo y Barrio Romántico','Polo urbano de gran tradición hostelera. Sus barrios históricos albergan una densidad madura de negocios de restauración y ocio nocturno declaradamente inclusivos o especializados. Su Orgullo anual y los eventos culturales invernales atraen flujos continuos del noroeste peninsular y Asturias, consolidando un turismo de corta estancia de perfil cultural de nivel medio-alto.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','lgtbi','Orgullo de Palencia y red asociativa cultural','Actividad acotada estrictamente a la semana del Orgullo a nivel provincial. Su planta de alojamiento registra picos de ocupación puntuales durante sus jornadas de visibilidad, basando el resto de su oferta en un modelo turístico generalista sin turoperación específica.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','lgtbi','Salamanca Pride, locales de ocio nocturno mixto y especializado en el entorno de la Plaza Mayor y zona universitaria, y hoteles boutique inclusivos','Gran ciudad universitaria de renombre internacional. Su ambiente cosmopolita favorece un tejido empresarial permanente muy abierto, con locales especializados bien integrados. Registra una afluencia constante de turismo idiomático, joven y académico internacional del colectivo durante todo el año, mitigando la estacionalidad estival y generando un impacto económico recurrente en el sector servicios y el alojamiento del centro histórico.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','lgtbi','Orgullo de Segovia y alojamientos históricos de alta gama con protocolos de hospitalidad inclusiva','Municipio con un fuerte posicionamiento en el turismo patrimonial y gastronómico de alta rentabilidad. Su proximidad a Madrid y conexión AVE facilitan un flujo masivo y constante de parejas del colectivo que realizan excursiones o pernoctaciones de fin de semana, manteniendo el dinamismo de sus hoteles y restaurantes boutique de forma desestacionalizada.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','lgtbi','Orgullo de Soria y actividades de visibilidad rural-urbana','Núcleo urbano con infraestructuras limitadas al ámbito asociativo. El Orgullo provincial ejerce una función tractora muy puntual en el calendario anual, atrayendo visitantes de las comarcas vecinas sin contar con un tejido de negocios especializados permanente.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','lgtbi','CinHomo (Muestra Internacional de Cine y Derechos Humanos LGTBIQ+), Orgullo de Valladolid y ejes de ocio/comercio especializado en el distrito centro','Es el principal polo de atracción del colectivo en el sector central de la meseta norte. CinHomo es un festival cinematográfico de gran prestigio y larga trayectoria nacional que atrae a miles de asistentes. El centro urbano cuenta con una red madura de pubs, discotecas y comercios especializados. Su excelente infraestructura hotelera corporativa y conectividad por alta velocidad consolidan un turismo cultural y de negocios muy sólido durante todo el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49275','lgtbi','Orgullo de Zamora y actividades culturales de visibilidad en el casco histórico','Capital provincial con una oferta centrada en el turismo monumental de corte románico. Su Orgullo anual dinamiza de forma puntual el sector hostelero del centro de la ciudad en fechas específicas de la primavera. Carece de infraestructuras permanentes de nicho exclusivas.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','lgtbi','Barrio del Gaixample (histórico hub urbano, comercial y residencial), Pride! Barcelona (macroevento internacional), Circuit Festival (el mayor festival de ocio nocturno y cultural LGTBIQ+ del mundo), ','Superpotencia turística global. El Gaixample (delimitado en la Izquierda del Ensanche) concentra cientos de comercios, sedes corporativas, consultorías y locales especializados. El Pride! Barcelona y el Circuit Festival atraen de forma combinada a más de 300.000 turistas de los cinco continentes cada año, generando un impacto económico superior a los 150 millones de euros. Sus playas urbanas (Mar Bella) cuentan con chiringuitos e infraestructura identitaria permanente. Su planta hotelera exclusiva y la conectividad de su aeropuerto garantizan un turismo de negocios, congresos y vacacional totalmente desestacionalizado y de altísima rentabilidad durante los doce meses del año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','lgtbi','Playa de la Bassa Rodona, Playa de Balmins y Playa del Muerto (primeras playas LGTBI catalogadas de Europa); Sitges Pride, Sitges International Fantastic Film Festival (con secciones especializadas) y','Máxima puntuación de la escala. Sitges es el hito histórico y el destino costero LGTBIQ+ por excelencia de Europa desde mediados del siglo XX. Prácticamente todo el municipio opera como un hub de hospitalidad inclusiva y especializada, registrando picos de ocupación hotelera del 100% desde mayo hasta octubre. Su Pride es el único de carácter internacional de Europa que se celebra directamente a pie de playa. Sus calas naturales y playas urbanas son iconos globales. Cuenta con una altísima tasa de turismo residencial internacional de rentas muy elevadas y su cercanía con Barcelona le permite mantener flujos turísticos de fin de semana durante todo el invierno, eliminando el impacto de la estacionalidad tradicional.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90035','lgtbi','Cala Sa Conca y Cala del Pi (tramos de uso naturista con alta concurrencia del colectivo), y hoteles boutique con políticas de gestión inclusivas de la Costa Brava','Destino costero de perfil premium en la Costa Brava. Sus calas protegidas y entornos residenciales atraen a un turismo LGTBIQ+ internacional de alto poder adquisitivo (principalmente mercados francés, holandés y belga). El municipio se caracteriza por una planta hotelera de alta gama muy adaptada a la diversidad, registrando un elevado gasto en restauración y comercios de lujo durante toda la temporada estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18005','lgtbi','Orgullo de Girona, red de alojamientos de encanto en el Barri Vell e iniciativas de turismo gastronómico y cicloturismo inclusivo','Polo cultural y gastronómico de renombre internacional. Su casco histórico alberga una oferta de comercio y restauración muy abierta que capta el turismo de escapada de fin de semana y cultural. Su excelente conectividad por alta velocidad y su consolidación como meca mundial del ciclismo atraen a un perfil LGTBIQ+ joven y deportivo de rentas medias-altas durante todo el año, mitigando la estacionalidad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','lgtbi','Orgullo de Lleida y muestras de cine y cultura diversa organizadas por el tejido asociativo local','Capital provincial con una oferta centrada en eventos institucionales y asociativos en fechas específicas. Su planta hotelera absorbe una demanda de proximidad y de rango autonómico. Carece de infraestructuras de ocio o turoperación comercial especializada de carácter permanente.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43905','lgtbi','Cala Crancs y Cala Font (tramos naturistas y de socialización diversa), y grandes resorts vacacionales familiares con certificaciones de hospitalidad inclusiva','Gran polo de turismo vacacional de la Costa Daurada. Ha sabido posicionarse de forma madura en el segmento del turismo familiar LGTBIQ+ a nivel europeo. Sus grandes complejos hoteleros y parques temáticos cercanos (PortAventura) aplican políticas activas de diversidad. Atrae flujos masivos de los mercados británico, irlandés y francés de mayo a octubre, generando un fuerte impacto económico directo.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','lgtbi','Orgullo de Tarragona, Playa de la Savinosa (histórica playa nudista y referente LGTBIQ+ de la provincia) y eventos de visibilidad en el casco antiguo','Ciudad Patrimonio de la Humanidad que combina turismo monumental y de litoral. La Playa de la Savinosa es un hito de socialización natural plenamente consolidado en el noreste peninsular. Su Orgullo anual y su oferta hostelera de rango medioalto atraen flujos desestacionalizados de fin de semana, vinculados fuertemente al turismo de cruceros y arqueológico.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','lgtbi','Alicante Pride (Orgullo de Alicante), locales especializados en el Casco Antiguo / Zona Centro, y Playa de la Amadraba (puntos de socialización)','Gran nodo urbano y portuario con una oferta comercial y hostelería inclusiva en pleno auge. Su Orgullo anual congrega flujos masivos de la propia provincia y de comunidades interiores como Castilla-La Mancha y Madrid. Su excelente conectividad (AVE y Aeropuerto de Alicante-Elche) favorece un turismo residencial e internacional (principalmente británico y nórdico) desestacionalizado de fin de semana, con un impacto económico directo muy sólido en su planta hotelera urbana de nivel medio-alto.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','lgtbi','Benidorm Pride (macroevento internacional de cierre de temporada europea), Benidorm Pink Weekend, Casco Antiguo / "Zona Guiri" (hub urbano con más de 30 locales y bares de ambiente especializados), y ','Destino icónico y uno de los grandes referentes nacionales. Su casco antiguo concentra un entramado hiperdenso de locales y hoteles orientados al nicho LGTBIQ+. El Benidorm Pride, celebrado en septiembre, estira de forma masiva la temporada estival atrayendo a decenas de miles de turistas del Reino Unido y Europa central, inyectando millones de euros directos. Su planta hotelera y sus rascacielos operan de manera plenamente inclusiva bajo estándares de la IGLTA, logrando romper la estacionalidad y garantizando una ocupación superior al 80% durante los meses de invierno gracias al fuerte turismo sénior europeo.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46105','lgtbi','Playa del Marenyet (tramo de playa naturista e histórica zona de socialización LGTBIQ+) y festivales de música electrónica inclusivos','Destino costero tradicional que ha consolidado su tramo sur de playa (Marenyet) como un potente polo de atracción estacional para el colectivo madrileño y valenciano. Genera un notable impacto económico indirecto en la planta de apartamentos turísticos y hostelería durante el periodo estival. Su oferta se complementa con la cercanía a la capital de la autonomía.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46131','lgtbi','Playa de l''Ahuir (una de las playas nudistas y naturales mejor preservadas de la Comunidad Valenciana con alta afluencia LGTBIQ+) y red hotelera vacacional con certificaciones de hospitalidad','Importante núcleo turístico del litoral valenciano. La Playa de l''Ahuir funciona de manera estacional como un imán para el turismo LGTBIQ+ que busca entornos vírgenes y protegidos, alejados de la masificación urbana. Su planta hotelera en la zona de la playa cuenta con establecimientos adaptados al segmento familiar y de adultos del colectivo, registrando un volumen de gasto medio-alto en restauración y comercio local durante los meses de junio a septiembre.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','lgtbi','Orgullo de Valencia (Valencia Pride), locales especializados en el barrio del Carmen y Ruzafa (hubs urbanos de alta densidad), y Playa de Pinedo (zona de la playa canina/ naturista con fuerte tradició','Gran referente nacional e internacional en pleno crecimiento y consolidación cultural. Los distritos céntricos de Ruzafa y El Carmen operan como auténticos hubs de ocio, galerías de arte, librerías y comercios especializados con un tejido empresarial maduro. Su Orgullo anual atrae flujos millonarios de visitantes y su designación histórica para eventos internacionales de gran formato ha catapultado su marca de ciudad inclusiva. Gracias a su conexión por AVE y aeropuerto internacional, capta turismo europeo y americano desestacionalizado de perfil cultural, tecnológico y corporativo de alta rentabilidad durante todo el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','lgtbi','Los Palomos (macroevento transfronterizo de gran formato LGTBIQ+), locales de ocio inclusivo en el casco antiguo y red hotelera urbana','Destino que rompe los estándares de las capitales de interior gracias a "Los Palomos", un festival multitudinario que congrega anualmente a más de 30.000 personas. Atrae masivamente a turistas del centro peninsular, Andalucía y del mercado emisor de Portugal debido a su carácter fronterizo, generando un impacto económico directo millonario y el llenado absoluto de la planta hotelera provincial. El resto del año mantiene una oferta de ocio y restauración de carácter mixto-friendly bien integrada.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','lgtbi','Orgullo de Mérida (Extremadura Pride), red de alojamientos históricos e iniciativas de turismo cultural inclusivo en el Festival de Teatro Clásico','Capital autonómica y conjunto arqueológico Patrimonio de la Humanidad. Centraliza los actos del Orgullo regional de forma estacional. Sus infraestructuras hoteleras y turísticas de alta gama aprovechan el Festival de Teatro Clásico en verano para captar un perfil de turista LGTBIQ+ cultural de rentas medias-altas, logrando un fuerte impacto económico indirecto en los meses estivales.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','lgtbi','Orgullo de Cáceres, alojamientos boutique en la ciudad monumental y eventos culturales de diversidad','Destino monumental enfocado al turismo de fin de semana y escapadas de interior. Su Orgullo anual dinamiza el sector hostelero del centro histórico. La planta alojativa boutique, de gran encanto, registra visitas desestacionalizadas de parejas del colectivo procedentes principalmente de Madrid, atraídas por la gastronomía y el patrimonio.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','lgtbi','Coruña Pride (Atlantic Pride / Orgullo del Norte), locales de comercio y ocio especializado en el Distrito Centro / Orzán, y Playa de las Amorosas (histórico punto costero de socialización)','Gran polo de atracción del noroeste español. El festival "Atlantic Pride" se ha consolidado como un macroevento de referencia que atrae a miles de visitantes de Galicia, Asturias y León, inyectando un notable volumen de gasto en su red hotelera. El tejido empresarial de ocio nocturno y comercial en zonas como el Orzán cuenta con una densidad madura. Su perfil turístico es urbano, cultural y de negocios, funcionando con baja estacionalidad a lo largo del año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','lgtbi','Santiago Pride (Orgullo de Santiago), muestras de cine diverso (Cineuropa con secciones LGTBIQ+) y alojamientos turísticos inclusivos','Epicentro cultural y meta del Camino de Santiago. Su carácter cosmopolita e internacional propicia un ambiente de alta hospitalidad. Atrae de manera desestacionalizada a un gran volumen de peregrinos y turistas internacionales del colectivo que demandan hoteles con encanto y restauración de nivel medio-alto. Cuenta con locales de ambiente nocturno mixto y actividades culturales de diversidad plenamente consolidadas en el calendario de la ciudad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','lgtbi','Orgullo de Lugo y jornadas culturales de diversidad en la zona monumental','Actividad identitaria acotada estrictamente a la semana de visibilidad institucional. Su planta de alojamiento del centro histórico, delimitada por la muralla romana, registra picos de ocupación puntuales de rango provincial, basando el resto de su oferta en un modelo turístico generalista.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34008','lgtbi','Orgullo de Ourense y red de turismo termal adaptada a directrices inclusivas','Capital de interior con una oferta turística fuertemente ligada al termalismo. Su Orgullo anual atrae flujos de corta estancia. El sector hotelero y de balnearios aplica políticas "friendly" que captan turismo de fin de semana y bienestar procedente de otras provincias gallegas y del norte de Portugal gracias a su conectividad ferroviaria por alta velocidad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','lgtbi','Playa de Barra (considerada la playa nudista de referencia absoluta en Galicia y una de las más concurridas por el colectivo LGTBIQ+ del norte peninsular)','Destino costero con un potente imán natural. La Playa de Barra, situada en el espacio protegido de Cabo Udra, atrae masivamente en verano a turistas del colectivo de toda Galicia, Asturias y el norte de Portugal. Genera un fuerte impacto económico indirecto en los campings, casas rurales y establecimientos hoteleros tradicionales de la península del Morrazo durante el periodo estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36015','lgtbi','Vigo Orgullo, locales especializados en el barrio de Churruca y Casco Vello, y red hotelera internacional inclusiva','El mayor núcleo urbano de Galicia, con un consolidado hub de ocio nocturno y comercial diverso en la zona de Churruca. Su Orgullo anual y los eventos culturales atraen flujos constantes. Su planta hotelera absorbe un turismo corporativo, comercial y de escapadas de fin de semana que mitiga con éxito la estacionalidad invernal, apoyado por la alta conectividad de su área de influencia.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','lgtbi','Barrio de Chueca (hub urbano, comercial, residencial y asociativo de referencia mundial), MADO / Madrid Orgullo (el mayor macroevento e infraestructura cultural LGTBIQ+ de Europa), Festival de Cine Le','Máxima calificación de la escala junto a Sitges y Maspalomas. Chueca opera como el epicentro definitivo del turismo urbano, corporativo y comercial LGTBIQ+ del continente europeo, con centenares de negocios hiperespecializados operativos los 365 días del año. Su orgullo anual (MADO) congrega de forma sistemática a más de un millón de visitantes internacionales de los cinco continentes, inyectando más de 150 millones de euros directos en la economía local, el transporte y la planta hotelera, que registra ocupación absoluta. Alberga el certamen cinematográfico especializado más importante de habla hispana (LesGaiCineMad). Su excelente conectividad (Aeropuerto Madrid-Barajas, alta velocidad) y su oferta permanente cultural, de compras y ocio garantizan la eliminación completa de la estacionalidad, manteniendo flujos de muy alta rentabilidad durante todo el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','lgtbi','Playa de la Galera y Playa de la Grúa (tramos de litoral vírgenes de uso naturista y alta concurrencia del colectivo), y eventos del Carnaval con fuerte impronta de diversidad','Destino costero con un marcado perfil de turismo de naturaleza y litoral estacional. Sus playas salvajes y calas protegidas atraen flujos turísticos de la propia Región de Murcia, Almería y del interior peninsular durante el verano. Genera un impacto económico indirecto en la planta de apartamentos, hostelería local y campings de la zona.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','lgtbi','EnorgulleceCT (Orgullo de Cartagena), Calblanque (Playa de Parreño / tramos naturistas de alta concurrencia LGTBIQ+), y alojamientos boutique inclusivos en el centro histórico','Importante nodo cultural, portuario y arqueológico. Su festival de orgullo está plenamente consolidado a nivel regional. El Parque Natural de Calblanque alberga calas vírgenes de fuerte tradición para el colectivo, atrayendo turismo nacional durante la temporada estival. Su planta hotelera y monumental capta un turismo de cruceros y de escapadas de fin de semana que ayuda a mantener el dinamismo económico de manera desestacionalizada.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','lgtbi','Murcia Pride (Orgullo de Murcia), locales de ocio nocturno y hostelería especializada en el centro urbano (entorno de la Plaza de las Flores y San Juan)','Principal polo urbano de la provincia que centraliza el tejido asociativo y las grandes movilizaciones del Orgullo autonómico, atrayendo flujos del sureste peninsular y Castilla-La Mancha. Dispone de una red comercial y de ocio nocturno mixto-friendly estable y madura. Su planta hotelera absorbe un turismo cultural, gastronómico y de congresos de corta estancia, operando de manera recurrente durante todo el año y rompiendo los picos de estacionalidad turística gracias a su conectividad por alta velocidad.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','lgtbi','Orgullo de Pamplona (Iruña Pride), locales de ocio diverso en el Casco Antiguo (San Nicolás / Navarrería) y muestras de cine inclusivo','Capital autonómica que centraliza el dinamismo asociativo y cultural del territorio. Su Orgullo anual y los ciclos de cine especializado atraen flujos de fin de semana procedentes del País Vasco, La Rioja y Aragón. El sector hostelero del casco histórico está fuertemente adaptado al turismo internacional gracias a la proyección global de la ciudad, ofreciendo una alta hospitalidad y captando turismo cultural y gastronómico desestacionalizado fuera de su festividad mayor.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','lgtbi','Orgullo de Vitoria, red de locales hosteleros inclusivos en la Almendra Medieval y actividades de visibilidad sociocultural','Capital institucional vasca con un modelo de ciudad sostenible y cohesionada. El tejido comercial y hostelero de su casco histórico presenta un alto grado de integración y políticas de espacio seguro de forma permanente. Su Orgullo anual ejerce una función tractora de rango autonómico, generando picos de pernoctación de corta estancia enfocados al turismo verde, cultural y de congresos.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90950','lgtbi','Playa de Muriola (Cala de Barrika), hito del litoral nudista y de socialización diversa en el entorno natural vizcaíno','Espacio de litoral salvaje y protegido de fuerte arraigo naturista y LGTBIQ+. Su proyección mediática internacional en los últimos años ha incrementado la afluencia estacional de turistas del norte de Europa. Genera un impacto económico indirecto centrado en el sector de la restauración y alojamientos de agroturismo de la comarca de Uribe Kosta.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','lgtbi','Bilbao Bizkaia Pride (macroevento regional-nacional), Zinegoak (Festival Internacional de Cine LGTBIQ+ de referencia en el norte de España), y eje de ocio especializado en los barrios de Bilbao La Vie','Gran hub cultural y de vanguardia urbana del norte peninsular. Destaca internacionalmente por el festival Zinegoak, que atrae a cineastas y visitantes de todo el mundo a principios de año, rompiendo la estacionalidad hotelera. Su Bilbao Bizkaia Pride congrega flujos masivos. Los barrios de San Francisco y Bilbao La Vieja albergan una alta densidad de comercios, locales hosteleros, librerías y galerías de arte especializadas. Su planta hotelera de primer nivel y su conectividad aérea consolidan un turismo de rentas medias-altas enfocado en el arte, la gastronomía y los negocios durante todo el año.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90956','lgtbi','Playa de Barinatxe (La Salvaje) y Playa de Atxabiribil (tramos nudistas e infraestructuras deportivas inclusivas)','Destino costero referencial que fusiona el turismo activo y de surf con la tradición naturista. Barinatxe es un hito de socialización estival para el colectivo. Atrae a un perfil de turista joven e internacional de perfil deportivo, generando una elevada rentabilidad en escuelas de surf, cámpings avanzados y hostelería local entre junio y septiembre.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','lgtbi','La Rioja Orgullo, locales de restauración y ocio mixto-friendly en el entorno de la Calle Laurel y Casco Antiguo','Capital autonómica que centraliza el tejido asociativo y las actividades del Orgullo regional, atrayendo flujos del norte y del interior peninsular. Su estrategia turística aprovecha el enoturismo y la gastronomía premium para captar un perfil de visitante LGTBIQ+ de rentas medias-altas en formato de escapadas de fin de semana. Sus hoteles cuentan con altos estándares de hospitalidad inclusiva, logrando mantener una afluencia constante e independiente de la estacionalidad estival.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12001','lgtbi','Orgullo de Ceuta y actividades de visibilidad sociocultural organizadas en el núcleo urbano','Ciudad autónoma norteafricana con actividades identitarias acotadas estrictamente a las jornadas de visibilidad institucional y asociativa. Su planta hotelera absorbe una demanda de proximidad muy puntual. El impacto económico en el sector servicios se concentra en fechas específicas del calendario anual, presentando un modelo turístico de carácter generalista y una baja densidad de infraestructuras específicas estables para el colectivo.','inventario_turismo_lgtbi_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('52001','lgtbi','Orgullo de Melilla (Melilla Pride) y eventos de visibilidad integrados en la agenda cultural de la ciudad','Enclave norteafricano cuya actividad turística LGTBIQ+ se activa estacionalmente durante la celebración de su Orgullo, dinamizando de manera puntual el transporte marítimo/aéreo y los servicios de alojamiento locales. Funciona principalmente como un recurso de sensibilización y visibilidad en un entorno multicultural, careciendo de un hub empresarial o comercial de ambiente permanente. La Base de Datos y Ranking de Destinos de Turismo LGTBIQ+ de España ha sido completada en su totalidad siguiendo de forma estricta los criterios de jerarquía, orden alfabético, filtros de exclusión y formato Markdown requeridos para su exportación a Microsoft Word. Si lo desea, podemos avanzar con la siguiente fase del proyecto. Elija una opción para proceder: • Generar el top 10 definitivo de destinos con puntuación internacional (95-100).','inventario_turismo_lgtbi_pdf');
